def count_pairs(xs, k):
    """
    Returns the number of index pairs (i, j) such that i < j and xs[i] + xs[j] == k.
    """
    if not isinstance(xs, list):
        raise TypeError("First parameter must be a list.")
    if not xs:
        return 0

    count = 0
    for i in range(len(xs)):
        for j in range(i + 1, len(xs)):
            if xs[i] + xs[j] == k:
                count += 1
    return count
