def running_max(xs):
    """Returns a list where each element is the maximum value seen so far from the beginning of the input list up to that position."""
    if not isinstance(xs, list):
        raise TypeError
    result = []
    current_max = None
    for x in xs:
        if current_max is None or x > current_max:
            current_max = x
        result.append(current_max)
    return result
