def dedupe_sorted(xs):
    """
    Returns a new list of sorted elements with duplicates removed, preserving the order.
    """
    if not isinstance(xs, list):
        raise TypeError("First argument must be a list.")

    if not xs:
        return []

    result = [xs[0]]
    for i in range(1, len(xs)):
        if xs[i] != result[-1]:
            result.append(xs[i])
    return result
```

